# Native NGA-West2 GMPE equations generated from audit-only VBA.
# This file is generated by scripts/generate_ngaw2_gmpe_native.py.

.excel_col_number <- function(label) {
  chars <- strsplit(label, "", fixed = TRUE)[[1]]
  out <- 0
  for (ch in chars) {
    out <- out * 26 + utf8ToInt(ch) - 64
  }
  out
}

.cof <- function(model, period) {
  lookup_period <- if (model == "CB14" && as.numeric(period) == 0) 0.001 else as.numeric(period)
  data <- load_coefficients(model)
  rows <- data[abs(as.numeric(data$period_s) - lookup_period) < 1e-9, ]
  if (nrow(rows) == 0L) {
    stop(sprintf("No coefficients for %s period %s", model, period), call. = FALSE)
  }
  labels <- sub("^([A-Z]+).*$", "\\1", rows$source_cell)
  rows$source_col <- vapply(labels, .excel_col_number, numeric(1))
  rows <- rows[order(rows$source_col), ]
  values <- rows$value
  missing <- is.na(values)
  values[missing] <- rows$cached_value[missing]
  as.numeric(values)
}

pgar_calc <- function(m, rjb, u, rs, ns, region, t) {
  c1 <- 0
  c2 <- 0
  c3 <- 0
  counter <- 0
  dc3 <- 0
  dc3chtur <- 0
  dc3jpit <- 0
  e0 <- 0
  e1 <- 0
  e2 <- 0
  e3 <- 0
  e4 <- 0
  e5 <- 0
  e6 <- 0
  fm <- 0
  fp <- 0
  h <- 0
  mh <- 0
  mref <- 0
  pgar <- 0
  r <- 0
  rref <- 0
  ss <- 0
  cof <- .cof("BSSA14", t)
  e0 <- cof[[1]]
  e1 <- cof[[2]]
  e2 <- cof[[3]]
  e3 <- cof[[4]]
  e4 <- cof[[5]]
  e5 <- cof[[6]]
  e6 <- cof[[7]]
  mh <- cof[[8]]
  c1 <- cof[[9]]
  c2 <- cof[[10]]
  c3 <- cof[[11]]
  mref <- cof[[12]]
  rref <- cof[[13]]
  h <- cof[[14]]
  dc3 <- cof[[15]]
  dc3chtur <- cof[[16]]
  dc3jpit <- cof[[17]]
  if (ns == 0 && rs == 0 && u == 0) {
    ss <- 1
  } else {
    ss <- 0
  }
  if (m <= mh) {
    fm <- e0 * u + e1 * ss + e2 * ns + e3 * rs + e4 * (m - mh) + e5 * (m - mh) ^ 2
  } else {
    fm <- e0 * u + e1 * ss + e2 * ns + e3 * rs + e6 * (m - mh)
  }
  r <- sqrt(rjb ^ 2 + h ^ 2)
  if (region == 0) {
    fp <- (c1 + c2 * (m - mref)) * log(r / rref) + (c3 + dc3) * (r - rref)
  } else if (region == 3 || region == 5) {
    fp <- (c1 + c2 * (m - mref)) * log(r / rref) + (c3 + dc3chtur) * (r - rref)
  } else if (region == 1 || region == 4) {
    fp <- (c1 + c2 * (m - mref)) * log(r / rref) + (c3 + dc3jpit) * (r - rref)
  } else {
    fp <- (c1 + c2 * (m - mref)) * log(r / rref) + (c3 + dc3) * (r - rref)
  }
  pgar <- exp(fm + fp)
  return(pgar)
}

dz1_calc <- function(vs30, z1, region, t) {
  dz1 <- 0
  mz1 <- 0
  if (region == 1) {
    mz1 <- exp(-5.23 / 2 * log((vs30 ^ 2 + 412.39 ^ 2) / (1360 ^ 2 + 412.39 ^ 2))) / 1000
  } else {
    mz1 <- exp(-7.15 / 4 * log((vs30 ^ 4 + 570.94 ^ 4) / (1360 ^ 4 + 570.94 ^ 4))) / 1000
  }
  dz1 <- z1 - mz1
  return(dz1)
}

i_14_raw <- function(m, rrup, f, vs30, t) {
  a11 <- 0
  a12 <- 0
  a21 <- 0
  a22 <- 0
  a3 <- 0
  b11 <- 0
  b12 <- 0
  b21 <- 0
  b22 <- 0
  counter <- 0
  fatn <- 0
  fdis <- 0
  fflt <- 0
  fm <- 0
  fsite <- 0
  g <- 0
  ksi <- 0
  phi <- 0
  y <- 0
  cof <- .cof("I14", t)
  a11 <- cof[[1]]
  a21 <- cof[[2]]
  b11 <- cof[[3]]
  b21 <- cof[[4]]
  a12 <- cof[[5]]
  a22 <- cof[[6]]
  b12 <- cof[[7]]
  b22 <- cof[[8]]
  a3 <- cof[[9]]
  ksi <- cof[[10]]
  g <- cof[[11]]
  phi <- cof[[12]]
  if (m <= 6.75) {
    fm <- a21 * m + a3 * (8.5 - m) ^ 2
  } else {
    fm <- a22 * m + a3 * (8.5 - m) ^ 2
  }
  if (m <= 6.75) {
    fdis <- -(b11 + b21 * m) * log(rrup + 10)
  } else {
    fdis <- -(b12 + b22 * m) * log(rrup + 10)
  }
  if (vs30 < 1200) {
    fsite <- ksi * log(vs30)
  } else {
    fsite <- ksi * log(1200)
  }
  fatn <- g * rrup
  fflt <- phi * f
  if (m <= 6.75) {
    y <- exp(a11 + fm + fdis + fsite + fatn + fflt)
  } else {
    y <- exp(a12 + fm + fdis + fsite + fatn + fflt)
  }
  return(y)
}

