  } else {
    w <- w
  }
  z25r <- (1 - sj) * exp(7.089 - 1.144 * log(1100)) + sj * exp(5.359 - 1.102 * log(1100))
  if (z25 == 999) {
    z25 <- z25r
  } else {
    z25 <- z25
  }
  if (m <= 4.5) {
    fmag <- (c1 * m)
  } else if (m <= 5.5) {
    fmag <- (c1 * m) + (c2 * (m - 4.5))
  } else if (m <= 6.5) {
    fmag <- (c1 * m) + (c2 * (m - 4.5)) + (c3 * (m - 5.5))
