  if (f2_rx > 0) {
    maxr <- f2_rx
  } else {
    maxr <- 0
  }
  if (fhw == 0) {
    fhngrx <- 0
  } else if (rx < r1 && fhw == 1) {
    fhngrx <- f1_rx
  } else if (rx >= r1 && fhw == 1) {
    fhngrx <- maxr
  }
  if (rrup == 0) {
    fhngr <- 1
  } else if (rrup > 0) {
    fhngr <- (rrup - rjb) / rrup
