  if (f2_rx > 0) {
    f2x <- f2_rx
  } else {
    f2x <- 0
  }
  if (m <= 5.5) {
    fhngm <- 0
  } else if (m <= 6.5) {
    fhngm <- (m - 5.5) * (1 + a2 * (m - 6.5))
  } else if (m > 6.5) {
    fhngm <- 1 + a2 * (m - 6.5)
  }
  if (ztor < 16.66) {
    fhngz <- 1 - 0.06 * ztor
  } else if (ztor >= 16.66) {
    fhngz <- 0
  }
  fhngs <- (90 - delta) / 45
  fhng <- c10 * fhngrx * fhngr * fhngm * fhngz * fhngs
  if (z25 <= 1) {
    fsed <- (c14 + c15 * sj) * (z25 - 1)
  } else if (z25 > 1 && z25 <= 3) {
    fsed <- 0
  } else {
    fsed <- c16 * k3 * exp(-0.75) * (1 - exp(-0.25 * (z25 - 3)))
  }
  if (zhyp <= 7) {
    fhyph <- 0
  } else if (zhyp > 7 && zhyp <= 20) {
    fhyph <- zhyp - 7
  } else {
    fhyph <- 13
  }
  if (m <= 5.5) {
    fhypm <- c17
  } else if (m > 5.5 && m <= 6.5) {
    fhypm <- c17 + (c18 - c17) * (m - 5.5)
  } else {
    fhypm <- c18
  }
  fhyp <- fhyph * fhypm
  if (m <= 4.5) {
    fdip <- c19 * delta
  } else if (m > 4.5 && m <= 5.5) {
    fdip <- c19 * (5.5 - m) * delta
  } else {
    fdip <- 0
  }
  if (region == 0) {
    dc20 <- dc20ca
  } else if (region == 1 || region == 4) {
    dc20 <- dc20jp
  } else if (region == 3) {
    dc20 <- dc20ch
  } else {
    dc20 <- dc20ca
  }
  if (rrup > 80) {
    fatn <- (c20 + dc20) * (rrup - 80)
  } else if (rrup <= 80) {
    fatn <- 0
  }
  if (z25r < 1) {
    a1100 <- c0 + fmag + fdis + fflt + fhng + fhyp + fdip + fatn +      (c11 + k2 * n) * log(1100 / k1) + sj * (c13 + k2 * n) * log(1100 / k1) +      (c14 + sj * c15) * (z25r - 1)
  } else if (z25r > 3) {
    a1100 <- c0 + fmag + fdis + fflt + fhng + fhyp + fdip + fatn +      (c11 + k2 * n) * log(1100 / k1) + sj * (c13 + k2 * n) * log(1100 / k1) +      c16 * k3 * exp(-0.75) * (1 - exp(-0.25 * (z25r - 3)))
  } else {
    a1100 <- c0 + fmag + fdis + fflt + fhng + fhyp + fdip + fatn +      (c11 + k2 * n) * log(1100 / k1) + sj * (c13 + k2 * n) * log(1100 / k1)
  }
  y <- exp(a1100)
  return(y)
}

cb_14_raw <- function(m, rrup, rjb, rx, frv, fnm, fhw, ztor, w, delta, vs30, z25, zhyp, ztord, wd, zhypd, region, a, t) {
  a2 <- 0
  c <- 0
