      t5 <- 1 - (ry0 - ry1) / 5
    } else {
      t5 <- 0
    }
  } else {
    if (rjb == 0) {
      t5 <- 1
    } else if (rjb < 30) {
      t5 <- 1 - rjb / 30
    } else {
      t5 <- 0
    }
  }
  if (fhw == 1) {
    f4 <- a13 * t1 * t2 * t3 * t4 * t5
  } else {
    f4 <- 0
  }
  if (region == 1) {
    br <- (a41 + (1180 - 850) * (a42 - a41) / (1150 - 850))
  } else if (region == 2) {
    br <- a31 * log(1180 / vlin)
  } else {
    br <- 0
  }
  if (region == 1) {
    by <- a29
  } else if (region == 3) {
    by <- a28
  } else if (region == 2) {
    by <- a25
  } else {
    by <- 0
  }
  bs <- by * rrup + br
  if (1180 >= v1) {
    vs30star1180 <- v1
  } else {
    vs30star1180 <- 1180
  }
  bq <- (a10 + b * n) * log(vs30star1180 / vlin)
  if (ztor <= 20) {
    f6 <- a15 * ztor / 20
  } else if (ztor > 20) {
    f6 <- a15
  }
  sa1180 <- exp(f1 + f6 + frv * f7 + fnm * f8 + fhw * f4 + bq + bs)
  if (region != 1) {
    if (vs30flag == 0) {
      s1 <- s1
      s2 <- s2
    } else if (vs30flag == 1) {
      s1 <- s1v
      s2 <- s2v
    }
    if (m < 4) {
      phia <- s1
    } else if (m <= 6) {
      phia <- s1 + (s2 - s1) / 2 * (m - 4)
    } else {
      phia <- s2
    }
  } else {
    if (rrup < 30) {
      phia <- s5
    } else if (rrup <= 80) {
      phia <- s5 + (s6 - s5) / 50 * (rrup - 30)
    } else if (rrup > 80) {
      phia <- s6
    }
  }
  if (m < 5) {
    taua <- s3
  } else if (m <= 7) {
    taua <- s3 + (s4 - s3) / 2 * (m - 5)
  } else {
    taua <- s4
  }
  taub <- taua
  phib <- sqrt(phia ^ 2 - samp ^ 2)
  if (vs30 >= vlin) {
    ratio <- 0
  } else {
    ratio <- b * sa1180 * (-1 / (sa1180 + c) + 1 / (sa1180 + c * (vs30 / vlin) ^ n))
  }
  tau <- taub * (1 + ratio)
  phi <- sqrt(phib ^ 2 * (1 + ratio) ^ 2 + samp ^ 2)
  sigma <- sqrt(tau ^ 2 + phi ^ 2)
  sd <- sigma
  return(sd)
}

